import apps.organizations.models

PERMISSIONS = (
    ("tenant_policies.view", "مشاهده سیاست‌های Tenant"),
    ("tenant_policies.approve", "تأیید انتخاب سیاست‌های Tenant"),
    ("tenant_policies.apply", "اعمال سیاست‌های تأییدشده Tenant"),
)


def register_policy_permissions(apps, schema_editor):
    del schema_editor
    Permission = apps.get_model("organizations", "BusinessPermission")
    Role = apps.get_model("organizations", "OrganizationRole")
    values = {
        code: Permission.objects.update_or_create(
            code=code,
            defaults={"name": name, "description": name, "is_active": True},
        )[0]
        for code, name in PERMISSIONS
    }
    grants = {
        "tenant_owner": tuple(values),
        "tenant_admin": ("tenant_policies.view", "tenant_policies.apply"),
        "tenant_manager": ("tenant_policies.view",),
        "project_manager": ("tenant_policies.view",),
        "company_owner": tuple(values),
        "company_manager": ("tenant_policies.view", "tenant_policies.apply"),
        "operations_manager": ("tenant_policies.view",),
        "accountant": ("tenant_policies.view",),
        "supervisor": ("tenant_policies.view",),
        "member": ("tenant_policies.view",),
        "viewer": ("tenant_policies.view",),
    }
    for role_code, permission_codes in grants.items():
        role = Role.objects.filter(code=role_code, organization__isnull=True).first()
        if role is not None:
            role.permissions.add(*(values[code] for code in permission_codes))


def reverse_policy_foundation(apps, schema_editor):
    del schema_editor
    for model_name in (
        "TenantPolicySelection",
        "PolicyReviewEvidence",
        "PlatformPolicyVersion",
        "PlatformPolicy",
        "PolicySource",
    ):
        if apps.get_model("organizations", model_name).objects.exists():
            raise RuntimeError(
                "Unsafe P1-S15 rollback refused: policy/source/evidence history exists."
            )
    apps.get_model("organizations", "BusinessPermission").objects.filter(
        code__in=[code for code, _ in PERMISSIONS]
    ).delete()


